mapper.select:
select r.recharge_id, r.member_id, m.phone, r.currency, r.amount, r.status,
       r.audit_by, r.audit_time, r.audit_remark, r.create_time, r.remark,
       r.pay_mode, r.channel_code, r.out_trade_no
from biz_recharge r
left join biz_member m on m.member_id = r.member_id

    and r.member_id = #{memberId}
    and r.currency = #{currency}
    and r.status = #{status}
    and m.phone like concat('%', #{phone}, '%')
    and r.create_time >= #{params.beginTime}
    and r.create_time < date_add(#{params.endTime}, interval 1 day)

order by r.recharge_id desc

select ifnull(sum(r.amount), 0)
from biz_recharge r
inner join biz_member m on m.member_id = r.member_id
where r.currency = #{currency} and r.status = '1'
  and ifnull(m.test_flag, '0') = '0'
  and (
    (
      find_in_set(#{memberId}, m.ancestors)

        and (length(ifnull(m.ancestors,'')) - length(replace(ifnull(m.ancestors,''), ',', '')) - ifnull(#{viewerDepth}, 0)) between 1 and #{maxDepth}

    )
    or m.member_id = #{memberId}
  )

mapper.update:
update biz_recharge
status = #{status}, audit_by = #{auditBy}, audit_time = #{auditTime}, audit_remark = #{auditRemark}, pay_mode = #{payMode}, channel_code = #{channelCode}, out_trade_no = #{outTradeNo},
where recharge_id = #{rechargeId}
